// Modified C# port of Go go1.27.1 src/slices/zsortanyfunc.go; exact SortFunc closure.
// Original source generated by gen_sort_variants.go; stable merging shares this span backing.
#nullable disable
namespace TypeScript.Scanner;
internal static partial class GoSliceSort
{
    private static void insertionSortCmpFunc<E>(Span<E> data, int a, int b, Comparison<E> cmp)
    {
        for (var i = a + 1; i < b; i++)
            for (var j = i; j > a && cmp(data[j], data[j - 1]) < 0; j--)
                (data[j], data[j - 1]) = (data[j - 1], data[j]);
    }

    private static void siftDownCmpFunc<E>(Span<E> data, int lo, int hi, int first, Comparison<E> cmp)
    {
        var root = lo;
        while (true)
        {
            var child = 2 * root + 1;
            if (child >= hi)
                break;
            if (child + 1 < hi && cmp(data[first + child], data[first + child + 1]) < 0)
                child++;
            if (!(cmp(data[first + root], data[first + child]) < 0))
                return;
            (data[first + root], data[first + child]) = (data[first + child], data[first + root]);
            root = child;
        }
    }

    private static void heapSortCmpFunc<E>(Span<E> data, int a, int b, Comparison<E> cmp)
    {
        var first = a;
        var lo = 0;
        var hi = b - a;
        for (var i = (hi - 1) / 2; i >= 0; i--)
            siftDownCmpFunc(data, i, hi, first, cmp);
        for (var i = hi - 1; i >= 0; i--)
        {
            (data[first], data[first + i]) = (data[first + i], data[first]);
            siftDownCmpFunc(data, lo, i, first, cmp);
        }
    }

    private static void pdqsortCmpFunc<E>(Span<E> data, int a, int b, int limit, Comparison<E> cmp)
    {
        const int maxInsertion = 12;
        var wasBalanced = true;
        var wasPartitioned = true;
        while (true)
        {
            var length = b - a;
            if (length <= maxInsertion)
            {
                insertionSortCmpFunc(data, a, b, cmp);
                return;
            }

            if (limit == 0)
            {
                heapSortCmpFunc(data, a, b, cmp);
                return;
            }

            if (!wasBalanced)
            {
                breakPatternsCmpFunc(data, a, b, cmp);
                limit--;
            }

            var(pivot, hint) = choosePivotCmpFunc(data, a, b, cmp);
            if (hint == sortedHint.decreasingHint)
            {
                reverseRangeCmpFunc(data, a, b, cmp);
                pivot = (b - 1) - (pivot - a);
                hint = sortedHint.increasingHint;
            }

            if (wasBalanced && wasPartitioned && hint == sortedHint.increasingHint)
                if (partialInsertionSortCmpFunc(data, a, b, cmp))
                    return;
            if (a > 0 && !(cmp(data[a - 1], data[pivot]) < 0))
            {
                var mid = partitionEqualCmpFunc(data, a, b, pivot, cmp);
                a = mid;
                continue;
            }

            var(newMid, alreadyPartitioned) = partitionCmpFunc(data, a, b, pivot, cmp);
            wasPartitioned = alreadyPartitioned;
            var leftLen = newMid - a;
            var rightLen = b - newMid;
            var balanceThreshold = length / 8;
            if (leftLen < rightLen)
            {
                wasBalanced = leftLen >= balanceThreshold;
                pdqsortCmpFunc(data, a, newMid, limit, cmp);
                a = newMid + 1;
            }
            else
            {
                wasBalanced = rightLen >= balanceThreshold;
                pdqsortCmpFunc(data, newMid + 1, b, limit, cmp);
                b = newMid;
            }
        }
    }

    private static (int newpivot, bool alreadyPartitioned) partitionCmpFunc<E>(Span<E> data, int a, int b, int pivot, Comparison<E> cmp)
    {
        (data[a], data[pivot]) = (data[pivot], data[a]);
        var i = a + 1;
        var j = b - 1;
        while (i <= j && cmp(data[i], data[a]) < 0)
            i++;
        while (i <= j && !(cmp(data[j], data[a]) < 0))
            j--;
        if (i > j)
        {
            (data[j], data[a]) = (data[a], data[j]);
            return (j, true);
        }

        (data[i], data[j]) = (data[j], data[i]);
        i++;
        j--;
        while (true)
        {
            while (i <= j && cmp(data[i], data[a]) < 0)
                i++;
            while (i <= j && !(cmp(data[j], data[a]) < 0))
                j--;
            if (i > j)
                break;
            (data[i], data[j]) = (data[j], data[i]);
            i++;
            j--;
        }

        (data[j], data[a]) = (data[a], data[j]);
        return (j, false);
    }

    private static int partitionEqualCmpFunc<E>(Span<E> data, int a, int b, int pivot, Comparison<E> cmp)
    {
        (data[a], data[pivot]) = (data[pivot], data[a]);
        var i = a + 1;
        var j = b - 1;
        while (true)
        {
            while (i <= j && !(cmp(data[a], data[i]) < 0))
                i++;
            while (i <= j && cmp(data[a], data[j]) < 0)
                j--;
            if (i > j)
                break;
            (data[i], data[j]) = (data[j], data[i]);
            i++;
            j--;
        }

        return i;
    }

    private static bool partialInsertionSortCmpFunc<E>(Span<E> data, int a, int b, Comparison<E> cmp)
    {
        const int maxSteps = 5;
        const int shortestShifting = 50;
        var i = a + 1;
        for (var step = 0; step < maxSteps; step++)
        {
            while (i < b && !(cmp(data[i], data[i - 1]) < 0))
                i++;
            if (i == b)
                return true;
            if (b - a < shortestShifting)
                return false;
            (data[i], data[i - 1]) = (data[i - 1], data[i]);
            if (i - a >= 2)
                for (var j = i - 1; j >= 1; j--)
                {
                    if (!(cmp(data[j], data[j - 1]) < 0))
                        break;
                    (data[j], data[j - 1]) = (data[j - 1], data[j]);
                }

            if (b - i >= 2)
                for (var j = i + 1; j < b; j++)
                {
                    if (!(cmp(data[j], data[j - 1]) < 0))
                        break;
                    (data[j], data[j - 1]) = (data[j - 1], data[j]);
                }
        }

        return false;
    }

    private static void breakPatternsCmpFunc<E>(Span<E> data, int a, int b, Comparison<E> cmp)
    {
        var length = b - a;
        if (length >= 8)
        {
            var random = new XorShift((ulong)length);
            var modulus = nextPowerOfTwo(length);
            for (var idx = a + (length / 4) * 2 - 1; idx <= a + (length / 4) * 2 + 1; idx++)
            {
                var other = (int)(random.Next() & (modulus - 1));
                if (other >= length)
                    other -= length;
                (data[idx], data[a + other]) = (data[a + other], data[idx]);
            }
        }
    }

    private static (int pivot, sortedHint hint) choosePivotCmpFunc<E>(Span<E> data, int a, int b, Comparison<E> cmp)
    {
        const int shortestNinther = 50;
        const int maxSwaps = 4 * 3;
        var l = b - a;
        var swaps = 0;
        var i = a + l / 4 * 1;
        var j = a + l / 4 * 2;
        var k = a + l / 4 * 3;
        if (l >= 8)
        {
            if (l >= shortestNinther)
            {
                i = medianAdjacentCmpFunc(data, i, ref swaps, cmp);
                j = medianAdjacentCmpFunc(data, j, ref swaps, cmp);
                k = medianAdjacentCmpFunc(data, k, ref swaps, cmp);
            }

            j = medianCmpFunc(data, i, j, k, ref swaps, cmp);
        }

        switch (swaps)
        {
            case 0:
                return (j, sortedHint.increasingHint);
            case maxSwaps:
                return (j, sortedHint.decreasingHint);
            default:
                return (j, sortedHint.unknownHint);
        }
    }

    private static (int, int) order2CmpFunc<E>(Span<E> data, int a, int b, ref int swaps, Comparison<E> cmp)
    {
        if (cmp(data[b], data[a]) < 0)
        {
            swaps++;
            return (b, a);
        }

        return (a, b);
    }

    private static int medianCmpFunc<E>(Span<E> data, int a, int b, int c, ref int swaps, Comparison<E> cmp)
    {
        (a, b) = order2CmpFunc(data, a, b, ref swaps, cmp);
        (b, c) = order2CmpFunc(data, b, c, ref swaps, cmp);
        (a, b) = order2CmpFunc(data, a, b, ref swaps, cmp);
        return b;
    }

    private static int medianAdjacentCmpFunc<E>(Span<E> data, int a, ref int swaps, Comparison<E> cmp) => medianCmpFunc(data, a - 1, a, a + 1, ref swaps, cmp);
    private static void reverseRangeCmpFunc<E>(Span<E> data, int a, int b, Comparison<E> cmp)
    {
        var i = a;
        var j = b - 1;
        while (i < j)
        {
            (data[i], data[j]) = (data[j], data[i]);
            i++;
            j--;
        }
    }

    // Go 1.27.1 slices/zsortanyfunc.go:329–487. Same stable merge/rotation
    // algorithm as Go; spans adapt only storage, with no auxiliary array.
    private static void swapRangeCmpFunc<E>(Span<E> data, int a, int b, int n, Comparison<E> cmp)
    {
        for (int i = 0; i < n; i++)
            (data[a + i], data[b + i]) = (data[b + i], data[a + i]);
    }

    private static void stableCmpFunc<E>(Span<E> data, int n, Comparison<E> cmp)
    {
        // Match Go's 64-bit int for doubled block boundaries beyond span length.
        long blockSize = 20, b = blockSize;
        int a = 0;
        while (b <= n)
        {
            insertionSortCmpFunc(data, a, (int)b, cmp);
            a = (int)b;
            b += blockSize;
        }
        insertionSortCmpFunc(data, a, n, cmp);
        while (blockSize < n)
        {
            a = 0;
            b = 2 * blockSize;
            while (b <= n)
            {
                symMergeCmpFunc(data, a, (int)(a + blockSize), (int)b, cmp);
                a = (int)b;
                b += 2 * blockSize;
            }
            long m = a + blockSize;
            if (m < n) symMergeCmpFunc(data, a, (int)m, n, cmp);
            blockSize *= 2;
        }
    }

    private static void symMergeCmpFunc<E>(Span<E> data, int a, int m, int b, Comparison<E> cmp)
    {
        if (m - a == 1)
        {
            int i = m, j = b;
            while (i < j)
            {
                int h = (int)(((uint)i + (uint)j) >> 1);
                if (cmp(data[h], data[a]) < 0) i = h + 1;
                else j = h;
            }
            for (int k = a; k < i - 1; k++)
                (data[k], data[k + 1]) = (data[k + 1], data[k]);
            return;
        }
        if (b - m == 1)
        {
            int i = a, j = m;
            while (i < j)
            {
                int h = (int)(((uint)i + (uint)j) >> 1);
                if (!(cmp(data[m], data[h]) < 0)) i = h + 1;
                else j = h;
            }
            for (int k = m; k > i; k--)
                (data[k], data[k - 1]) = (data[k - 1], data[k]);
            return;
        }
        int mid = (int)(((uint)a + (uint)b) >> 1);
        long n = (long)mid + m; // Go int is 64-bit; intermediate sums can exceed a CLR index.
        int start, r;
        if (m > mid)
        {
            start = (int)(n - b);
            r = mid;
        }
        else
        {
            start = a;
            r = m;
        }
        long p = n - 1;
        while (start < r)
        {
            int c = (int)(((uint)start + (uint)r) >> 1);
            if (!(cmp(data[(int)(p - c)], data[c]) < 0)) start = c + 1;
            else r = c;
        }
        int end = (int)(n - start);
        if (start < m && m < end) rotateCmpFunc(data, start, m, end, cmp);
        if (a < start && start < mid) symMergeCmpFunc(data, a, start, mid, cmp);
        if (mid < end && end < b) symMergeCmpFunc(data, mid, end, b, cmp);
    }

    private static void rotateCmpFunc<E>(Span<E> data, int a, int m, int b, Comparison<E> cmp)
    {
        int i = m - a, j = b - m;
        while (i != j)
        {
            if (i > j)
            {
                swapRangeCmpFunc(data, m - i, m, j, cmp);
                i -= j;
            }
            else
            {
                swapRangeCmpFunc(data, m - i, m + j - i, i, cmp);
                j -= i;
            }
        }
        swapRangeCmpFunc(data, m - i, m, i, cmp);
    }
}
